<script lang="ts">
import { authClient } from '$lib/auth-client';
let name=$state('');let email=$state('');let password=$state('');let busy=$state(false);let message=$state('');
async function submit(e:SubmitEvent){e.preventDefault();busy=true;message='';try{const result=await authClient.signUp.email({name,email,password,callbackURL:'/sign-in'});if(result.error)message=result.error.message??'Unable to create account';else message='Account created. Check your email for a verification link before signing in.';}catch{message='Auth is not configured or is unreachable';}finally{busy=false;}}
</script>
<svelte:head><title>Create account · Kid Postgres</title></svelte:head><main class="auth-wrap"><form class="auth-card" onsubmit={submit}><a href="/" class="text-violet-300 text-sm">← Kid StarterPack</a><h1 class="text-3xl font-bold mt-6">Create account.</h1><p class="text-slate-400 mt-2">Local Postgres, first-class sessions.</p>{#if message}<p role="status" class="mt-5 text-sm text-slate-300">{message}</p>{/if}<label for="name" class="label">Name</label><input class="field" id="name" bind:value={name} required maxlength="100" autocomplete="name"/><label for="email" class="label">Email</label><input class="field" id="email" bind:value={email} type="email" required autocomplete="email"/><label for="password" class="label">Password (8+ characters)</label><input class="field" id="password" bind:value={password} type="password" minlength="8" maxlength="128" required autocomplete="new-password"/><button class="primary w-full mt-6" disabled={busy}>{busy?'Creating...':'Create account'}</button><p class="text-center text-slate-400 text-sm mt-6">Already registered? <a href="/sign-in" class="text-violet-300">Sign in</a></p><p class="mt-4 text-center text-sm"><a href="/verify-email" class="text-violet-300">Resend verification email</a></p></form></main>
